#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdatomic.h>
#include <stdbool.h>
#include <errno.h>

typedef struct {
    void *buffer;
    size_t capacity;
    size_t elem_size;
    atomic_size_t head;
    atomic_size_t tail;
} spsc_queue_t;

spsc_queue_t* spsc_queue_create(size_t capacity, size_t elem_size) {
    if (capacity == 0 || elem_size == 0) {
        errno = EINVAL;
        return NULL;
    }
    spsc_queue_t *q = (spsc_queue_t *)malloc(sizeof(spsc_queue_t));
    if (!q) {
        errno = ENOMEM;
        return NULL;
    }
    q->buffer = malloc(capacity * elem_size);
    if (!q->buffer) {
        free(q);
        errno = ENOMEM;
        return NULL;
    }
    q->capacity = capacity;
    q->elem_size = elem_size;
    atomic_init(&q->head, 0);
    atomic_init(&q->tail, 0);
    return q;
}

void spsc_queue_destroy(spsc_queue_t *q) {
    if (!q) return;
    free(q->buffer);
    free(q);
}

bool spsc_queue_push(spsc_queue_t *q, const void *elem) {
    if (!q || !elem) {
        errno = EINVAL;
        return false;
    }
    size_t head = atomic_load_explicit(&q->head, memory_order_relaxed);
    size_t tail = atomic_load_explicit(&q->tail, memory_order_acquire);
    if (((head + 1) % q->capacity) == tail) {
        errno = ENOBUFS;
        return false;
    }
    memcpy((char *)q->buffer + (head * q->elem_size), elem, q->elem_size);
    atomic_store_explicit(&q->head, (head + 1) % q->capacity, memory_order_release);
    return true;
}

bool spsc_queue_pop(spsc_queue_t *q, void *elem) {
    if (!q || !elem) {
        errno = EINVAL;
        return false;
    }
    size_t tail = atomic_load_explicit(&q->tail, memory_order_relaxed);
    size_t head = atomic_load_explicit(&q->head, memory_order_acquire);
    if (tail == head) {
        errno = ENODATA;
        return false;
    }
    memcpy(elem, (char *)q->buffer + (tail * q->elem_size), q->elem_size);
    atomic_store_explicit(&q->tail, (tail + 1) % q->capacity, memory_order_release);
    return true;
}

int main(void) {
    spsc_queue_t *q = spsc_queue_create(4, sizeof(int));
    if (!q) {
        perror("Failed to create queue");
        return 1;
    }
    int val = 42;
    if (spsc_queue_push(q, &val)) {
        printf("Pushed successfully: %d\n", val);
    }
    int out = 0;
    if (spsc_queue_pop(q, &out)) {
        printf("Popped successfully: %d\n", out);
    }
    spsc_queue_destroy(q);
    return 0;
}

