Here is a complete, production-ready MPMC bounded queue based on Dmitry Vyukov's lock-free algorithm in C++20.

```cpp
#include <atomic>
#include <vector>
#include <iostream>
#include <thread>

template <typename T, size_t Capacity>
class MPMCQueue {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be power of 2");

    struct Cell {
        std::atomic<size_t> sequence;
        T data;
    };

    Cell* buffer_;
    const size_t mask_;
    alignas(64) std::atomic<size_t> enqueue_pos_{0};
    alignas(64) std::atomic<size_t> dequeue_pos_{0};

public:
    MPMCQueue() : mask_(Capacity - 1) {
        buffer_ = new Cell[Capacity];
        for (size_t i = 0; i != Capacity; ++i) {
            buffer_[i].sequence.store(i, std::memory_order_relaxed);
        }
    }

    ~MPMCQueue() {
        delete[] buffer_;
    }

    bool enqueue(const T& data) {
        Cell* cell;
        size_t pos = enqueue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            cell = &buffer_[pos & mask_];
            size_t seq = cell->sequence.load(std::memory_order_acquire);
            intptr_t dif = (intptr_t)seq - (intptr_t)pos;
            if (dif == 0) {
                if (enqueue_pos_.compare_exchange_weak(pos, pos + 1,
                                                      std::memory_order_relaxed,
                                                      std::memory_order_relaxed)) {
                    break;
                }
            } else if (dif < 0) {
                return false;
            } else {
                pos = enqueue_pos_.load(std::memory_order_relaxed);
            }
        }
        cell->data = data;
        cell->sequence.store(pos + 1, std::memory_order_release);
        return true;
    }

    bool dequeue(T& data) {
        Cell* cell;
        size_t pos = dequeue_pos_.load(std::memory_order_relaxed);
        for (;;) {
            cell = &buffer_[pos & mask_];
            size_t seq = cell->sequence.load(std::memory_order_acquire);
            intptr_t dif = (intptr_t)seq - (intptr_t)(pos + 1);
            if (dif == 0) {
                if (dequeue_pos_.compare_exchange_weak(pos, pos + 1,
                                                      std::memory_order_relaxed,
                                                      std::memory_order_relaxed)) {
                    break;
                }
            } else if (dif < 0) {
                return false;
            } else {
                pos = dequeue_pos_.load(std::memory_order_relaxed);
            }
        }
        data = cell->data;
        cell->sequence.store(pos + mask_ + 1, std::memory_order_release);
        return true;
    }
};

int main() {
    MPMCQueue<int, 64> q;
    q.enqueue(42);
    int val;
    assert(q.dequeue(val) && val == 42);
    std::cout << "MPMC Queue verified successfully!" << std::endl;
    return 0;
}
```

### Complexity Analysis:
- **Time Complexity:** $\mathcal{O}(1)$ amortized per operation.
- **Space Complexity:** $\mathcal{O}(Capacity)$ fixed memory allocation.

Here is a complete, thread-safe worker pool thread coordinator implemented from scratch in Python.

```python
import threading
import queue
import time
from typing import Callable, Any

class SimpleThreadPool:
    def __init__(self, num_threads: int):
        self._tasks: queue.Queue[Callable[[], Any] | None] = queue.Queue()
        self._workers: list[threading.Thread] = []
        self._shutdown = False

        for _ in range(num_threads):
            t = threading.Thread(target=self._worker_loop)
            t.daemon = True
            t.start()
            self._workers.append(t)

    def _worker_loop(self) -> None:
        while not self._shutdown:
            try:
                task = self._tasks.get(timeout=0.1)
            except queue.Empty:
                continue

            if task is None:
                break

            try:
                task()
            except Exception as e:
                print(f"Task failed with exception: {e}")
            finally:
                self._tasks.task_done()

    def submit(self, func: Callable[[], Any]) -> None:
        if self._shutdown:
            raise RuntimeError("ThreadPool is shut down")
        self._tasks.put(func)

    def shutdown(self) -> None:
        self._shutdown = True
        for _ in self._workers:
            self._tasks.put(None)
        for t in self._workers:
            t.join()

if __name__ == "__main__":
    pool = SimpleThreadPool(2)
    results = []

    def sample_task():
        results.append(42)

    pool.submit(sample_task)
    time.sleep(0.2)
    pool.shutdown()
    assert results == [42]
    print("ThreadPool test passed successfully.")
```

### Complexity Analysis:
- **Time Complexity:** $\mathcal{O}(1)$ task submission time.
- **Space Complexity:** $\mathcal{O}(N)$ where $N$ is the number of queued tasks.

Here is a complete thread-safe Reference-Counted smart pointer implementation using atomic reference counts in C++.

```cpp
#include <atomic>
#include <iostream>
#include <thread>
#include <vector>

template <typename T>
class AtomicSharedPtr {
private:
    T* ptr_;
    std::atomic<long>* ref_count_;

public:
    explicit AtomicSharedPtr(T* ptr = nullptr)
        : ptr_(ptr), ref_count_(ptr ? new std::atomic<long>(1) : nullptr) {}

    ~AtomicSharedPtr() {
        release();
    }

    AtomicSharedPtr(const AtomicSharedPtr& other) noexcept {
        ptr_ = other.ptr_;
        ref_count_ = other.ref_count_;
        if (ref_count_) {
            ref_count_->fetch_add(1, std::memory_order_relaxed);
        }
    }

    AtomicSharedPtr& operator=(const AtomicSharedPtr& other) noexcept {
        if (this != &other) {
            release();
            ptr_ = other.ptr_;
            ref_count_ = other.ref_count_;
            if (ref_count_) {
                ref_count_->fetch_add(1, std::memory_order_relaxed);
            }
        }
        return *this;
    }

    T* get() const noexcept {
        return ptr_;
    }

    long use_count() const noexcept {
        return ref_count_ ? ref_count_->load(std::memory_order_relaxed) : 0;
    }

private:
    void release() noexcept {
        if (ref_count_ && ref_count_->fetch_sub(1, std::memory_order_acq_rel) == 1) {
            delete ptr_;
            delete ref_count_;
        }
    }
};

int main() {
    AtomicSharedPtr<int> p1(new int(10));
    {
        AtomicSharedPtr<int> p2 = p1;
        assert(p1.use_count() == 2);
    }
    assert(p1.use_count() == 1);
    std::cout << "AtomicSharedPtr passed verification!" << std::endl;
    return 0;
}
```

