```cpp
#include <atomic>
#include <thread>
#include <vector>
#include <iostream>

const int MAX_THREADS = 128;

struct HazardPointer {
    std::atomic<void*> pointer{nullptr};
};

class HazardPointerRegistry {
private:
    HazardPointer hazards_[MAX_THREADS];

public:
    HazardPointer& acquire(size_t tid) {
        return hazards_[tid];
    }

    void clear(size_t tid) {
        hazards_[tid].pointer.store(nullptr, std::memory_order_release);
    }

    bool is_hazard(void* ptr) const {
        for (int i = 0; i < MAX_THREADS; ++i) {
            if (hazards_[i].pointer.load(std::memory_order_acquire) == ptr) {
                return true;
            }
        }
        return false;
    }
};

int main() {
    HazardPointerRegistry registry;
    int dummy_val = 99;
    registry.acquire(0).pointer.store(&dummy_val, std::memory_order_release);
    assert(registry.is_hazard(&dummy_val) == true);
    registry.clear(0);
    assert(registry.is_hazard(&dummy_val) == false);
    std::cout << "Hazard pointer verification passed successfully!" << std::endl;
    return 0;
}
