Here is a complete, production-grade implementation of a lock-free MPSC bounded queue in C++20.

```cpp
#include <atomic>
#include <vector>
#include <optional>
#include <new>
#include <iostream>

template <typename T, size_t Capacity>
class MPSCQueue {
private:
    struct Node {
        std::atomic<T*> data{nullptr};
        std::atomic<Node*> next{nullptr};
    };

    alignas(64) Node* head_;
    alignas(64) std::atomic<Node*> tail_;
    Node stub_;

    // Prevent false sharing and cache line bouncing
    char pad_[64];

public:
    MPSCQueue() {
        stub_.next.store(nullptr, std::memory_order_relaxed);
        head_ = &stub_;
        tail_.store(&stub_, std::memory_order_relaxed);
    }

    ~MPSCQueue() {
        T* dummy;
        while (dequeue(dummy));
    }

    MPSCQueue(const MPSCQueue&) = delete;
    MPSCQueue& operator=(const MPSCQueue&) = delete;

    bool enqueue(T* item) {
        if (!item) return false;
        Node* newNode = new (std::nothrow) Node();
        if (!newNode) return false;
        newNode->data.store(item, std::memory_order_relaxed);
        newNode->next.store(nullptr, std::memory_order_relaxed);

        Node* prev = tail_.exchange(newNode, std::memory_order_acq_rel);
        prev->next.store(newNode, std::memory_order_release);
        return true;
    }

    bool dequeue(T*& item) {
        Node* tail = head_;
        Node* next = tail->next.load(std::memory_order_acquire);

        if (tail == &stub_) {
            if (!next) return false;
            head_ = next;
            tail = next;
            next = next->next.load(std::memory_order_acquire);
        }

        if (next) {
            item = next->data.load(std::memory_order_relaxed);
            head_ = next;
            delete tail;
            return true;
        }

        Node* tail_curr = tail_.load(std::memory_order_acquire);
        if (tail == tail_curr) {
            return false;
        }

        return false;
    }
};

int main() {
    MPSCQueue<int, 1024> queue;
    int* val = new int(42);
    if (queue.enqueue(val)) {
        std::cout << "Enqueued successfully\n";
    }
    int* out = nullptr;
    if (queue.dequeue(out)) {
        std::cout << "Dequeued: " << *out << "\n";
        delete out;
    }
    return 0;
}
```

