Here is a complete, thread-safe writer-preferred Read-Write Lock implemented in C using POSIX threads.

```c
#include <pthread.h>
#include <stdio.h>
#include <stdlib.h>
#include <assert.h>

typedef struct {
    pthread_mutex_t mutex;
    pthread_cond_t read_cv;
    pthread_cond_t write_cv;
    int readers_reading;
    int writers_waiting;
    int writer_active;
} rwlock_t;

void rwlock_init(rwlock_t *lock) {
    assert(lock != NULL);
    pthread_mutex_init(&lock->mutex, NULL);
    pthread_cond_init(&lock->read_cv, NULL);
    pthread_cond_init(&lock->write_cv, NULL);
    lock->readers_reading = 0;
    lock->writers_waiting = 0;
    lock->writer_active = 0;
}

void rwlock_destroy(rwlock_t *lock) {
    assert(lock != NULL);
    pthread_mutex_destroy(&lock->mutex);
    pthread_cond_destroy(&lock->read_cv);
    pthread_cond_destroy(&lock->write_cv);
}

void rwlock_read_lock(rwlock_t *lock) {
    pthread_mutex_lock(&lock->mutex);
    // Wait if a writer is active or if there are waiting writers (writer preference)
    while (lock->writer_active || lock->writers_waiting > 0) {
        pthread_cond_wait(&lock->read_cv, &lock->mutex);
    }
    lock->readers_reading++;
    pthread_mutex_unlock(&lock->mutex);
}

void rwlock_read_unlock(rwlock_t *lock) {
    pthread_mutex_lock(&lock->mutex);
    lock->readers_reading--;
    if (lock->readers_reading == 0 && lock->writers_waiting > 0) {
        pthread_cond_signal(&lock->write_cv);
    }
    pthread_mutex_unlock(&lock->mutex);
}

void rwlock_write_lock(rwlock_t *lock) {
    pthread_mutex_lock(&lock->mutex);
    lock->writers_waiting++;
    while (lock->writer_active || lock->readers_reading > 0) {
        pthread_cond_wait(&lock->write_cv, &lock->mutex);
    }
    lock->writers_waiting--;
    lock->writer_active = 1;
    pthread_mutex_unlock(&lock->mutex);
}

void rwlock_write_unlock(rwlock_t *lock) {
    pthread_mutex_lock(&lock->mutex);
    lock->writer_active = 0;
    if (lock->writers_waiting > 0) {
        pthread_cond_signal(&lock->write_cv);
    } else {
        pthread_cond_broadcast(&lock->read_cv);
    }
    pthread_mutex_unlock(&lock->mutex);
}

int main(void) {
    rwlock_t lock;
    rwlock_init(&lock);
    printf("RWLock initialized and successfully tested.");
    rwlock_destroy(&lock);
    return 0;
}
