Here is a complete, production-ready implementation of Dinic's Maximum Flow Algorithm in C++.

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <algorithm>
#include <stdexcept>

class DinicMaxFlow {
private:
    struct Edge {
        int to;
        long long capacity;
        long long flow;
        int rev;
    };

    int n;
    std::vector<std::vector<Edge>> adj;
    std::vector<int> level;
    std::vector<int> ptr;

    bool bfs(int s, int t) {
        std::fill(level.begin(), level.end(), -1);
        level[s] = 0;
        std::queue<int> q;
        q.push(s);

        while (!q.empty()) {
            int v = q.front();
            q.pop();

            for (const auto& edge : adj[v]) {
                if (edge.capacity - edge.flow > 0 && level[edge.to] == -1) {
                    level[edge.to] = level[v] + 1;
                    q.push(edge.to);
                }
            }
        }
        return level[t] != -1;
    }

    long long dfs(int v, int t, long long pushed) {
        if (pushed == 0) return 0;
        if (v == t) return pushed;

        for (int& cid = ptr[v]; cid < adj[v].size(); ++cid) {
            auto& edge = adj[v][cid];
            int tr = edge.to;

            if (level[v] + 1 != level[tr] || edge.capacity - edge.flow == 0) continue;

            long long tr_push = dfs(tr, t, std::min(pushed, edge.capacity - edge.flow));
            if (tr_push == 0) continue;

            edge.flow += tr_push;
            adj[tr][edge.rev].flow -= tr_push;
            return tr_push;
        }
        return 0;
    }

public:
    DinicMaxFlow(int vertices) : n(vertices) {
        if (vertices <= 0) {
            throw std::invalid_argument("Number of vertices must be positive.");
        }
        adj.resize(n);
        level.resize(n);
        ptr.resize(n);
    }

    void add_edge(int from, int to, long long capacity) {
        if (from < 0 || from >= n || to < 0 || to >= n) {
            throw std::out_of_range("Vertex index out of bounds.");
        }
        if (capacity < 0) {
            throw std::invalid_argument("Capacity cannot be negative.");
        }

        Edge a{to, capacity, 0, (int)adj[to].size()};
        Edge b{from, 0, 0, (int)adj[from].size()};
        adj[from].push_back(a);
        adj[to].push_back(b);
    }

    long long max_flow(int s, int t) {
        if (s < 0 || s >= n || t < 0 || t >= n) {
            throw std::out_of_range("Source or sink out of bounds.");
        }

        long long flow = 0;
        while (bfs(s, t)) {
            std::fill(ptr.begin(), ptr.end(), 0);
            while (long long pushed = dfs(s, t, 1e18)) {
                flow += pushed;
            }
        }
        return flow;
    }
};

int main() {
    try {
        DinicMaxFlow solver(4);
        solver.add_edge(0, 1, 10);
        solver.add_edge(0, 2, 5);
        solver.add_edge(1, 2, 15);
        solver.add_edge(1, 3, 10);
        solver.add_edge(2, 3, 10);

        std::cout << "Max Flow: " << solver.max_flow(0, 3) << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
```

