Here is a complete, runnable C++ implementation of Kahn's Algorithm for Topological Sorting.

```cpp
#include <iostream>
#include <vector>
#include <queue>
#include <stdexcept>

class TopologicalSort {
private:
    int n;
    std::vector<std::vector<int>> adj;
    std::vector<int> in_degree;

public:
    TopologicalSort(int vertices) : n(vertices) {
        if (vertices <= 0) {
            throw std::invalid_argument("Vertex count must be positive.");
        }
        adj.resize(n);
        in_degree.resize(n, 0);
    }

    void add_edge(int u, int v) {
        if (u < 0 || u >= n || v < 0 || v >= n) {
            throw std::out_of_range("Vertex index out of bounds.");
        }
        adj[u].push_back(v);
        in_degree[v]++;
    }

    std::vector<int> sort() {
        std::queue<int> q;
        for (int i = 0; i < n; ++i) {
            if (in_degree[i] == 0) {
                q.push(i);
            }
        }

        std::vector<int> topo_order;
        while (!q.empty()) {
            int u = q.front();
            q.pop();
            topo_order.push_back(u);

            for (int v : adj[u]) {
                if (--in_degree[v] == 0) {
                    q.push(v);
                }
            }
        }

        if (topo_order.size() != n) {
            throw std::runtime_error("Graph contains a cycle; topological sort is impossible.");
        }

        return topo_order;
    }
};

int main() {
    try {
        TopologicalSort ts(6);
        ts.add_edge(5, 2);
        ts.add_edge(5, 0);
        ts.add_edge(4, 0);
        ts.add_edge(4, 1);
        ts.add_edge(2, 3);
        ts.add_edge(3, 1);

        std::vector<int> order = ts.sort();
        std::cout << "Topological Sort: ";
        for (int node : order) {
            std::cout << node << " ";
        }
        std::cout << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** $O(V + E)$, where $V$ is the number of vertices and $E$ is the number of edges. Every vertex is processed once when its in-degree hits zero, and every edge is traversed once during degree decrement.
- **Space Complexity:** $O(V + E)$ for storing the adjacency list and the in-degree tracking array alongside the Kahn's algorithm queue.

