```python
from typing import List, Tuple

class BellmanFord:
    def __init__(self, num_vertices: int) -> None:
        if num_vertices <= 0:
            raise ValueError("Number of vertices must be greater than zero.")
        self.num_vertices = num_vertices
        self.edges: List[Tuple[int, int, float]] = []

    def add_edge(self, u: int, v: int, weight: float) -> None:
        if not (0 <= u < self.num_vertices and 0 <= v < self.num_vertices):
            raise IndexError("Vertex indices must be within valid range.")
        self.edges.append((u, v, weight))

    def shortest_paths(self, start_node: int) -> List[float]:
        if not (0 <= start_node < self.num_vertices):
            raise IndexError("Start node index out of bounds.")

        distances: List[float] = [float('inf')] * self.num_vertices
        distances[start_node] = 0.0

        # Relax all edges |V| - 1 times
        for _ in range(self.num_vertices - 1):
            updated = False
            for u, v, weight in self.edges:
                if distances[u] != float('inf') and distances[u] + weight < distances[v]:
                    distances[v] = distances[u] + weight
                    updated = True
            if not updated:
                break

        # Check for negative-weight cycles
        for u, v, weight in self.edges:
            if distances[u] != float('inf') and distances[u] + weight < distances[v]:
                raise ValueError("Graph contains a negative-weight cycle.")

        return distances

if __name__ == "__main__":
    try:
        bf = BellmanFord(5)
        bf.add_edge(0, 1, -1.0)
        bf.add_edge(0, 2, 4.0)
        bf.add_edge(1, 2, 3.0)
        bf.add_edge(1, 3, 2.0)
        bf.add_edge(1, 4, 2.0)
        bf.add_edge(3, 2, 5.0)
        bf.add_edge(3, 1, 1.0)
        bf.add_edge(4, 3, -3.0)

        distances = bf.shortest_paths(0)
        print("Shortest Distances:", distances)
    except Exception as e:
