Here is a complete, production-ready C++ implementation of a fixed-block bitmap allocator utilizing bitwise manipulation and intrinsic instructions for fast bit scanning.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cstddef>
#include <bit>

template <size_t TotalBlocks>
class BitmapAllocator {
private:
    static_assert(TotalBlocks > 0, "TotalBlocks must be greater than zero.");

    static constexpr size_t kBitsPerWord = 64;
    static constexpr size_t kNumWords = (TotalBlocks + kBitsPerWord - 1) / kBitsPerWord;

    uint64_t bitmap_[kNumWords] = {0};

    constexpr size_t word_index(size_t bit) const noexcept {
        return bit / kBitsPerWord;
    }

    constexpr uint64_t bit_mask(size_t bit) const noexcept {
        return 1ULL << (bit % kBitsPerWord);
    }

public:
    BitmapAllocator() = default;
    ~BitmapAllocator() = default;

    BitmapAllocator(const BitmapAllocator&) = delete;
    BitmapAllocator& operator=(const BitmapAllocator&) = delete;

    int64_t allocate() noexcept {
        for (size_t i = 0; i < kNumWords; ++i) {
            if (bitmap_[i] != ~0ULL) { // Word is not entirely full
                // Find the index of the first unset (0) bit
                unsigned long free_bit_offset = 0;
                uint64_t inverted = ~bitmap_[i];

                #if defined(_MSC_VER)
                _BitScanForward64(&free_bit_offset, inverted);
                #else
                free_bit_offset = __builtin_ctzll(inverted);
                #endif

                size_t block_index = i * kBitsPerWord + free_bit_offset;
                if (block_index < TotalBlocks) {
                    bitmap_[i] |= (1ULL << free_bit_offset);
                    return static_cast<int64_t>(block_index);
                }
            }
        }
        return -1; // Out of memory
    }

    bool free_block(size_t block_index) noexcept {
        if (block_index >= TotalBlocks) {
            return false;
        }

        size_t w_idx = word_index(block_index);
        uint64_t mask = bit_mask(block_index);

        if ((bitmap_[w_idx] & mask) == 0) {
            return false; // Double free or unallocated block
        }

        bitmap_[w_idx] &= ~mask;
        return true;
    }

    [[nodiscard]] bool is_allocated(size_t block_index) const noexcept {
        if (block_index >= TotalBlocks) {
            return false;
        }
        return (bitmap_[word_index(block_index)] & bit_mask(block_index)) != 0;
    }
};

int main() {
    BitmapAllocator<128> allocator;
    int64_t b1 = allocator.allocate();
    int64_t b2 = allocator.allocate();

    std::cout << "Allocated blocks: " << b1 << ", " << b2 << std::endl;

    allocator.free_block(b1);
    std::cout << "Is block 1 allocated? " << (allocator.is_allocated(b1) ? "Yes" : "No") << std::endl;

    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(N / 64)$ in the worst-case for `allocate()` where $N$ is the total number of blocks, optimized heavily by CPU bit-scan instructions (`__builtin_ctzll`). `free_block()` and `is_allocated()` run in $\mathcal{O}(1)$ time.
- **Space Complexity**: $\mathcal{O}(N / 64)$ space to track the allocation status, which requires minimal memory overhead (1 bit per block).

### Error Handling and Invariant Management
- Out-of-bounds checks for block indices prevent memory corruption.
- Prevents double-free scenarios by verifying that the target bit is set prior to clearing it.

Here is a robust, production-grade dynamic byte buffer implementation in C that handles allocation failures and capacity overflows explicitly.

```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdint.h>
#include <stdbool.h>

typedef struct {
    uint8_t* data;
    size_t size;
    size_t capacity;
} ByteBuffer;

ByteBuffer* byte_buffer_create(size_t initial_capacity) {
    if (initial_capacity == 0) {
        initial_capacity = 16; // Default fallback
    }
    ByteBuffer* buf = (ByteBuffer*)malloc(sizeof(ByteBuffer));
    if (!buf) {
        return NULL;
    }
    buf->data = (uint8_t*)malloc(initial_capacity);
    if (!buf->data) {
        free(buf);
        return NULL;
    }
    buf->size = 0;
    buf->capacity = initial_capacity;
    return buf;
}

void byte_buffer_destroy(ByteBuffer* buf) {
    if (buf) {
        if (buf->data) {
            memset(buf->data, 0, buf->capacity); // Zero-out memory for security
            free(buf->data);
        }
        free(buf);
    }
}

bool byte_buffer_reserve(ByteBuffer* buf, size_t new_capacity) {
    if (!buf || new_capacity <= buf->capacity) {
        return buf != NULL;
    }

    // Prevent integer overflow during capacity doubling
    if (new_capacity > SIZE_MAX / 2) {
        return false;
    }

    uint8_t* new_data = (uint8_t*)realloc(buf->data, new_capacity);
    if (!new_data) {
        return false;
    }

    buf->data = new_data;
    buf->capacity = new_capacity;
    return true;
}

bool byte_buffer_append(ByteBuffer* buf, const uint8_t* src, size_t len) {
    if (!buf || !src) {
        return false;
    }

    if (len == 0) {
        return true;
    }

    if (buf->size > SIZE_MAX - len) {
        return false; // Overflow check
    }

    size_t required_capacity = buf->size + len;
    if (required_capacity > buf->capacity) {
        size_t target_capacity = buf->capacity * 2;
        while (target_capacity < required_capacity) {
            if (target_capacity > SIZE_MAX / 2) {
                target_capacity = required_capacity; // Fallback to exact fit if doubling overflows
                break;
            }
            target_capacity *= 2;
        }

        if (!byte_buffer_reserve(buf, target_capacity)) {
            return false;
        }
    }

    memcpy(buf->data + buf->size, src, len);
    buf->size += len;
    return true;
}

int main(void) {
    ByteBuffer* buf = byte_buffer_create(32);
    if (!buf) {
        fprintf(stderr, "Memory allocation failed\n");
        return 1;
    }

    const char* msg = "Hello, Systems Programming!";
    if (!byte_buffer_append(buf, (const uint8_t*)msg, strlen(msg))) {
        fprintf(stderr, "Buffer append failed\n");
        byte_buffer_destroy(buf);
        return 1;
    }

    printf("Buffer size: %zu, capacity: %zu\nContent: %s\n", buf->size, buf->capacity, (char*)buf->data);
    byte_buffer_destroy(buf);
    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(1)$ amortized for appending bytes due to the geometric capacity doubling strategy. Direct index lookups and checks are $\mathcal{O}(1)$.
- **Space Complexity**: $\mathcal{O}(N)$ where $N$ represents the allocated capacity of the buffer.

### Error Handling and Invariant Management
- Strict validation of `NULL` pointers across all public interfaces.
- Arithmetic overflow checks (`SIZE_MAX` boundaries) prior to scaling allocations.
- Zero-initialization of sensitive memory blocks via `memset` prior to calling `free` to prevent memory scraping attacks.

