```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cstddef>
#include <stdexcept>
#include <bit>

class DynamicBitset {
private:
    size_t num_bits_;
    std::vector<uint64_t> words_;

    static constexpr size_t kBitsPerWord = 64;

    size_t word_index(size_t bit) const noexcept {
        return bit / kBitsPerWord;
    }

    uint64_t bit_mask(size_t bit) const noexcept {
        return 1ULL << (bit % kBitsPerWord);
    }

public:
    explicit DynamicBitset(size_t num_bits) 
        : num_bits_(num_bits), 
          words_((num_bits + kBitsPerWord - 1) / kBitsPerWord, 0) {}

    void set(size_t bit) {
        if (bit >= num_bits_) {
            throw std::out_of_range("Bit index out of range");
        }
        words_[word_index(bit)] |= bit_mask(bit);
    }

    void reset(size_t bit) {
        if (bit >= num_bits_) {
            throw std::out_of_range("Bit index out of range");
        }
        words_[word_index(bit)] &= ~bit_mask(bit);
    }

    [[nodiscard]] bool test(size_t bit) const {
        if (bit >= num_bits_) {
            throw std::out_of_range("Bit index out of range");
        }
        return (words_[word_index(bit)] & bit_mask(bit)) != 0;
    }

    [[nodiscard]] size_t count() const noexcept {
        size_t total = 0;
        for (uint64_t word : words_) {
            #if defined(_MSC_VER)
            total += __popcnt64(word);
            #else
            total += __builtin_popcountll(word);
            #endif
        }
        return total;
    }

    [[nodiscard]] size_t size() const noexcept {
        return num_bits_;
    }
};

int main() {
    DynamicBitset bs(100);
    bs.set(10);
    bs.set(65);

    std::cout << "Bit 10 set: " << (bs.test(10) ? "true" : "false") << std::endl;
    std::cout << "Bit 65 set: " << (bs.test(65) ? "true" : "false") << std::endl;
    std::cout << "Total set bits: " << bs.count() << std::endl;

    return 0;
}
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(1)$ for `set`, `reset`, and `test`. $\mathcal{O}(N / 64)$ for `count()`, where $N$ is the total number of bits, accelerated via hardware popcount instructions.
- **Space Complexity**: $\mathcal{O}(N)$ where the memory usage is tightly packed at 1 bit per element, utilizing 64-bit words.

### Error Handling and Invariant Management
- Throws `std::out_of_range` exceptions on all public accessors if an invalid bit index is requested.
- Ensures invariants are maintained by calculating exact word allocations during initialization.

Here is a complete, production-grade C++ RAII wrapper for a POSIX file descriptor.

```cpp
template <typename T>
#include <unistd.h>
#include <utility>
#include <system_error>
#include <cstring>

class ScopedFileDescriptor {
private:
    int fd_;

public:
    explicit ScopedFileDescriptor(int fd = -1) noexcept : fd_(fd) {}

    ~ScopedFileDescriptor() noexcept {
        close_descriptor();
    }

    ScopedFileDescriptor(const ScopedFileDescriptor&) = delete;
    ScopedFileDescriptor& operator=(const ScopedFileDescriptor&) = delete;

    ScopedFileDescriptor(ScopedFileDescriptor&& other) noexcept : fd_(other.fd_) {
        other.fd_ = -1;
    }

    ScopedFileDescriptor& operator=(ScopedFileDescriptor&& other) noexcept {
        if (this != &other) {
            close_descriptor();
            fd_ = other.fd_;
            other.fd_ = -1;
        }
        return *this;
    }

    void reset(int new_fd = -1) noexcept {
        if (fd_ != new_fd) {
            close_descriptor();
            fd_ = new_fd;
        }
    }

    [[nodiscard]] int release() noexcept {
        int temp = fd_;
        fd_ = -1;
        return temp;
    }

    [[nodiscard]] int get() const noexcept {
        return fd_;
    }

    [[nodiscard]] explicit operator bool() const noexcept {
        return fd_ != -1;
    }

private:
    void close_descriptor() noexcept {
        if (fd_ != -1) {
            while (close(fd_) == -1) {
                if (errno == EINTR) {
                    continue; // Retry if interrupted by signal
                }
                break; // Ignore other close errors in destructor to prevent termination
            }
            fd_ = -1;
        }
    }
};
```

### Complexity Analysis
- **Time Complexity**: $\mathcal{O}(1)$ for all wrapper methods (`reset`, `release`, `get`, move operations), and $\mathcal{O}(1)$ for resource destruction.
- **Space Complexity**: $\mathcal{O}(1)$ overhead beyond the scalar file descriptor integer storage.

