Here is a high-performance memory arena implementation in C featuring boundary checks and alignment calculations.

```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>
#include <string.h>
#include <assert.h>

typedef struct {
    uint8_t* buffer;
    size_t capacity;
    size_t offset;
} MemoryArena;

MemoryArena* arena_create(size_t capacity) {
    if (capacity == 0) return NULL;
    MemoryArena* arena = (MemoryArena*)malloc(sizeof(MemoryArena));
    if (!arena) return NULL;

    arena->buffer = (uint8_t*)malloc(capacity);
    if (!arena->buffer) {
        free(arena);
        return NULL;
    }
    arena->capacity = capacity;
    arena->offset = 0;
    return arena;
}

void* arena_alloc(MemoryArena* arena, size_t size, size_t alignment) {
    if (!arena || size == 0 || alignment == 0) return NULL;

    // Calculate alignment offset
    uintptr_t current_address = (uintptr_t)(arena->buffer + arena->offset);
    size_t alignment_padding = (alignment - (current_address % alignment)) % alignment;

    size_t total_size = size + alignment_padding;
    if (arena->offset + total_size > arena->capacity) {
        return NULL; // Out of memory in arena
    }

    void* ptr = (void*)(arena->buffer + arena->offset + alignment_padding);
    arena->offset += total_size;
    return ptr;
}

void arena_reset(MemoryArena* arena) {
    if (arena) {
        arena->offset = 0;
    }
}

void arena_destroy(MemoryArena* arena) {
    if (arena) {
        free(arena->buffer);
        free(arena);
    }
}

int main(void) {
    MemoryArena* arena = arena_create(1024);
    if (!arena) {
        fprintf(stderr, "Failed to create arena\n");
        return 1;
    }

    int* numbers = (int*)arena_alloc(arena, 10 * sizeof(int), sizeof(int));
    if (numbers) {
        for (int i = 0; i < 10; ++i) {
            numbers[i] = i * 10;
            printf("%d ", numbers[i]);
        }
        printf("\n");
    }

    arena_destroy(arena);
    return 0;
}
```

### Complexity Analysis:
- **Time Complexity:** 
  - `arena_alloc()`: $O(1)$ constant time pointer bump.
  - `arena_reset()`: $O(1)$ constant time offset reset.
- **Space Complexity:** $O(C)$ where $C$ is the static capacity allocated at initialization.

