// Constants
constexpr size_t PAGE_SIZE = 4096;
using page_id_t = int32_t;
using frame_id_t = int32_t;

constexpr page_id_t INVALID_PAGE_ID = -1;
constexpr frame_id_t INVALID_FRAME_ID = -1;

// Mock Disk Manager for demonstration
class DiskManager {
public:
    void ReadPage(page_id_t page_id, char *page_data) {
        if (page_id < 0) {
            throw std::invalid_argument("Invalid page ID for reading.");
        }
        // Simulate disk read by zeroing and stamping page_id
        std::memset(page_data, 0, PAGE_SIZE);
        std::memcpy(page_data, &page_id, sizeof(page_id_t));
    }

    void WritePage(page_id_t page_id, const char *page_data) {
        if (page_id < 0) {
            throw std::invalid_argument("Invalid page ID for writing.");
        }
        // Simulate disk write
    }
};

// LRU Replacer to manage unpinned frame evictions
class LRUReplacer {
public:
    explicit LRUReplacer(size_t num_pages) : capacity_(num_pages) {}

    bool Victim(frame_id_t *frame_id) {
        std::lock_guard<std::mutex> lock(latch_);
        if (lru_list_.empty()) {
            return false;
        }
        *frame_id = lru_list_.back();
        lru_map_.erase(*frame_id);
        lru_list_.pop_back();
        return true;
    }

    void Pin(frame_id_t frame_id) {
        std::lock_guard<std::mutex> lock(latch_);
        if (lru_map_.find(frame_id) != lru_map_.end()) {
            lru_list_.erase(lru_map_[frame_id]);
            lru_map_.erase(frame_id);
        }
    }

    void Unpin(frame_id_t frame_id) {
        std::lock_guard<std::mutex> lock(latch_);
        if (lru_map_.find(frame_id) != lru_map_.end()) {
            return;
        }
        if (lru_list_.size() >= capacity_) {
            throw std::runtime_error("LRUReplacer capacity exceeded during unpin.");
        }
        lru_list_.push_front(frame_id);
        lru_map_[frame_id] = lru_list_.begin();
    }

    size_t Size() {
        std::lock_guard<std::mutex> lock(latch_);
        return lru_list_.size();
    }

private:
    size_t capacity_;
    std::list<frame_id_t> lru_list_;
    std::unordered_map<frame_id_t, std::list<frame_id_t>::iterator> lru_map_;
    std::mutex latch_;
};

// Frame Header representing a physical frame in memory
class Frame {
public:
    char data_[PAGE_SIZE];
    page_id_t page_id_ = INVALID_PAGE_ID;
    int pin_count_ = 0;
    bool is_dirty_ = false;

    void Reset() {
        std::memset(data_, 0, PAGE_SIZE);
        page_id_ = INVALID_PAGE_ID;
        pin_count_ = 0;
        is_dirty_ = false;
    }
};

// Buffer Pool Manager
class BufferPoolManager {
public:
    BufferPoolManager(size_t pool_size, DiskManager *disk_manager)
        : pool_size_(pool_size), disk_manager_(disk_manager), replacer_(pool_size) {
        if (pool_size == 0 || disk_manager == nullptr) {
            throw std::invalid_argument("Invalid arguments to BufferPoolManager constructor.");
        }
        frames_ = new Frame[pool_size_];
        for (size_t i = 0; i < pool_size_; ++i) {
            free_list_.push_back(static_cast<frame_id_t>(i));
        }
    }

    ~BufferPoolManager() {
        FlushAllPages();
        delete[] frames_;
    }

    char *FetchPage(page_id_t page_id) {
        std::unique_lock<std::shared_mutex> lock(bpm_latch_);

        // 1. Check if page is already in buffer pool
        if (page_table_.find(page_id) != page_table_.end()) {
            frame_id_t frame_id = page_table_[page_id];
            frames_[frame_id].pin_count_++;
            replacer_.Pin(frame_id);
            return frames_[frame_id].data_;
        },

        // 2. Find a frame (either from free list or eviction)
        frame_id_t frame_id = INVALID_FRAME_ID;
        if (!FindAvailableFrame(&frame_id)) {
            return nullptr;
        }

        // 3. If frame contained a dirty page, write it back to disk
        Frame *frame = &frames_[frame_id];
        if (frame->page_id_ != INVALID_PAGE_ID) {
            if (frame->is_dirty_) {
                disk_manager_->WritePage(frame->page_id_, frame->data_);
                frame->is_dirty_ = false;
            }
            page_table_.erase(frame->page_id_);
        }

        // 4. Read new page from disk into frame
        disk_manager_->ReadPage(page_id, frame->data_);
        frame->page_id_ = page_id;
        frame->pin_count_ = 1;
        frame->is_dirty_ = false;

        page_table_[page_id] = frame_id;
        replacer_.Pin(frame_id);
        return frame->data_;
    }

    bool UnpinPage(page_id_t page_id, bool is_dirty) {
        std::unique_lock<std::shared_mutex> lock(bpm_latch_);

        if (page_table_.find(page_id) == page_table_.end()) {
            return false;
        }

        frame_id_t frame_id = page_table_[page_id];
        Frame *frame = &frames_[frame_id];

        if (frame->pin_count_ <= 0) {
            return false;
        }

        if (is_dirty) {
            frame->is_dirty_ = true;
        }

        frame->pin_count_--;
        if (frame->pin_count_ == 0) {
            replacer_.Unpin(frame_id);
        }

        return true;
    }

    bool FlushPage(page_id_t page_id) {
        std::unique_lock<std::shared_mutex> lock(bpm_latch_);

        if (page_table_.find(page_id) == page_table_.end()) {
            return false;
        }

        frame_id_t frame_id = page_table_[page_id];
        Frame *frame = &frames_[frame_id];

        if (frame->is_dirty_) {
            disk_manager_->WritePage(page_id, frame->data_);
            frame->is_dirty_ = false;
        }
        return true;
    }

    void FlushAllPages() {
        std::unique_lock<std::shared_mutex> lock(bpm_latch_);
        for (auto &pair : page_table_) {
            page_id_t page_id = pair.first;
            frame_id_t frame_id = pair.second;
            Frame *frame = &frames_[frame_id];
            if (frame->is_dirty_) {
                disk_manager_->WritePage(page_id, frame->data_);
                frame->is_dirty_ = false;
            }
        }
    }

private:
    bool FindAvailableFrame(frame_id_t *frame_id) {
        // Check free list first
        if (!free_list_.empty()) {
            *frame_id = free_list_.front();
            free_list_.pop_front();
            return true;
        }

        // Otherwise, use LRU Replacer to evict an unpinned frame
        if (replacer_.Victim(frame_id)) {
            return true;
        }

        return false;
    }

    size_t pool_size_;
    DiskManager *disk_manager_;
    Frame *frames_;
    std::unordered_map<page_id_t, frame_id_t> page_table_;
    std::list<frame_id_t> free_list_;
    LRUReplacer replacer_;
    std::shared_mutex bpm_latch_;
};

int main() {
    try {
        DiskManager disk_manager;
        BufferPoolManager bpm(2, &disk_manager);

        char *page1 = bpm.FetchPage(100);
        std::cout << "Fetched page 100 successfully.\n";

        // Mark page 100 dirty and unpin
        bpm.UnpinPage(100, true);

        char *page2 = bpm.FetchPage(200);
        std::cout << "Fetched page 200 successfully.\n";
        bpm.UnpinPage(200, false);

        // Fetching page 300 should evict page 100 or 200
        char *page3 = bpm.FetchPage(300);
        std::cout << "Fetched page 300 successfully, causing eviction.\n";
        bpm.UnpinPage(300, false);

        bpm.FlushAllPages();
        std::cout << "All pages flushed successfully.\n";
    } catch (const std::exception &e) {
        std::cerr << "Error: " << e.what() << "\n";
        return 1;
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:**
  - `FetchPage`: $O(1)$ average time complexity. Page table lookups and replacer updates take $O(1)$ time utilizing hash maps and doubly-linked lists. Disk I/O operations are considered external system calls and bounded by underlying disk storage speed.
  - `UnpinPage`: $O(1)$ time complexity due to direct hash map lookups and constant time list insertions/deletions.
  - `FlushPage` / `FlushAllPages`: $O(K)$ where $K$ is the number of active/dirty pages in the buffer pool.

- **Space Complexity:**
  - $O(N 	imes P)$ where $N$ is the buffer pool capacity (`pool_size`) and $P$ is the `PAGE_SIZE` (4096 bytes). The auxiliary data structures (`page_table_`, `free_list_`, `replacer_`) take $O(N)$ additional memory space.

Here is the complete C++ implementation of a Pratt precedence parser and evaluator. It includes a lexer, an AST node hierarchy, a Pratt parser with binding powers, and comprehensive error handling.

```cpp
#include <iostream>
#include <string>
#include <vector>
#include <memory>
#include <cctype>
#include <stdexcept>
#include <cmath>

enum class TokenType {
    Integer,
    Plus,
    Minus,
    Multiply,
    Divide,
    Power,
    LeftParen,
    RightParen,
    End
};

struct Token {
    TokenType type;
    std::string text;
    int value;
};

class Lexer {
    std::string src;
    size_t pos;
public:
    explicit Lexer(std::string source) : src(std::move(source)), pos(0) {}

    Token next_token() {
        while (pos < src.size() && std::isspace(src[pos])) {
            pos++;
        }
        if (pos >= src.size()) {
            return {TokenType::End, "", 0};
        }

        char c = src[pos];
        if (std::isdigit(c)) {
            int val = 0;
            while (pos < src.size() && std::isdigit(src[pos])) {
                val = val * 10 + (src[pos] - '0');
                pos++;
            }
            return {TokenType::Integer, "", val};
        }

        pos++;
        switch (c) {
            case '+': return {TokenType::Plus, "+", 0};
            case '-': return {TokenType::Minus, "-", 0};
            case '*': return {TokenType::Multiply, "*", 0};
            case '/': return {TokenType::Divide, "/", 0};
            case '^': return {TokenType::Power, "^", 0};
            case '(': return {TokenType::LeftParen, "(", 0};
            case ')': return {TokenType::RightParen, ")", 0};
            default:
                throw std::runtime_error(std::string("Unexpected character: ") + c);
        }
    }
};

enum class Precedence {
    LOWEST = 0,
    SUM = 10,
    PRODUCT = 20,
    PREFIX = 30,
    POWER = 40
};

class ASTNode {
public:
    virtual ~ASTNode() = default;
    virtual int evaluate() const = 0;
};

class IntegerNode : public ASTNode {
    int val;
public:
    explicit IntegerNode(int v) : val(v) {}
    int evaluate() const override { return val; }
};

class UnaryNode : public ASTNode {
    TokenType op;
    std::unique_ptr<ASTNode> rhs;
public:
    UnaryNode(TokenType o, std::unique_ptr<ASTNode> r) : op(o), rhs(std::move(r)) {}
    int evaluate() const override {
        int r_val = rhs->evaluate();
        if (op == TokenType::Minus) return -r_val;
        if (op == TokenType::Plus) return r_val;
        throw std::runtime_error("Unknown unary operator");
    }
};

class BinaryNode : public ASTNode {
    TokenType op;
    std::unique_ptr<ASTNode> lhs;
    std::unique_ptr<ASTNode> rhs;
public:
    BinaryNode(TokenType o, std::unique_ptr<ASTNode> l, std::unique_ptr<ASTNode> r) 
        : op(o), lhs(std::move(l)), rhs(std::move(r)) {}

    int evaluate() const override {
        int l_val = lhs->evaluate();
        int r_val = rhs->evaluate();
        switch (op) {
            case TokenType::Plus: return l_val + r_val;
            case TokenType::Minus: return l_val - r_val;
            case TokenType::Multiply: return l_val * r_val;
            case TokenType::Divide: 
                if (r_val == 0) throw std::runtime_error("Division by zero");
                return l_val / r_val;
            case TokenType::Power:
                return static_cast<int>(std::pow(l_val, r_val));
            default:
                throw std::runtime_error("Unknown binary operator");
        }
    }
};

class Parser {
    Lexer lexer;
    Token current_token;

    Token consume() {
        Token prev = current_token;
        current_token = lexer.next_token();
        return prev;
    }

    Precedence get_precedence(TokenType type) {
        switch (type) {
            case TokenType::Plus:
            case TokenType::Minus: return Precedence::SUM;
            case TokenType::Multiply:
            case TokenType::Divide: return Precedence::PRODUCT;
            case TokenType::Power: return Precedence::POWER;
            default: return Precedence::LOWEST;
        }
    }

    std::unique_ptr<ASTNode> parse_prefix() {
        if (current_token.type == TokenType::Integer) {
            int val = current_token.value;
            consume();
            return std::make_unique<IntegerNode>(val);
        }
        if (current_token.type == TokenType::Minus || current_token.type == TokenType::Plus) {
            TokenType op = current_token.type;
            consume();
            auto rhs = parse_expression(Precedence::PREFIX);
            return std::make_unique<UnaryNode>(op, std::move(rhs));
        }
        if (current_token.type == TokenType::LeftParen) {
            consume();
            auto node = parse_expression(Precedence::LOWEST);
            if (current_token.type != TokenType::RightParen) {
                throw std::runtime_error("Missing closing parenthesis");
            }
            consume();
            return node;
        }
        throw std::runtime_error("Unexpected token in prefix position");
    }

    std::unique_ptr<ASTNode> parse_infix(std::unique_ptr<ASTNode> left, TokenType op) {
        Precedence prec = get_precedence(op);
        // Right-associative exponentiation uses strict greater than; others use >= for left-associativity
        Precedence next_prec = (op == TokenType::Power) ? prec : static_cast<Precedence>(static_cast<int>(prec) + 1);
        consume();
        auto right = parse_expression(next_prec);
        return std::make_unique<BinaryNode>(op, std::move(left), std::move(right));
    }

public:
    explicit Parser(std::string source) : lexer(std::move(source)) {
        current_token = lexer.next_token();
    }

    std::unique_ptr<ASTNode> parse_expression(Precedence precedence) {
        auto left = parse_prefix();

        while (precedence < get_precedence(current_token.type)) {
            TokenType op = current_token.type;
            left = parse_infix(std::move(left), op);
        }

        return left;
    }
};

int main() {
    try {
        std::string expr = "-3 + 2 ^ 3 * 2 - (10 / 2)";
        Parser parser(expr);
        auto ast = parser.parse_expression(Precedence::LOWEST);
        std::cout << "Expression: " << expr << std::endl;
        std::cout << "Evaluated Result: " << ast->evaluate() << std::endl;
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
```

### Complexity Analysis
- **Time Complexity:** $\mathcal{O}(N)$ where $N$ is the number of tokens in the expression stream. Each token is visited and consumed a constant number of times by the lexer and parser.
- **Space Complexity:** $\mathcal{O}(D)$ where $D$ is the maximum depth of the AST and recursion stack. In the worst case of a deeply nested or skewed expression, this requires $\mathcal{O}(N)$ memory.

Here is the complete production-grade implementation of a Consistent Hashing Ring with virtual nodes in Python.

```python
import bisect
import hashlib
from typing import Dict, List, Set, Tuple


class ConsistentHashRing:
    def __init__(self, replicas: int = 100) -> None:
        if replicas <= 0:
            raise ValueError("Number of replicas per node must be greater than zero.")
        self.replicas: int = replicas
        self.ring: List[int] = []
        self.ring_map: Dict[int, str] = {}
        self.nodes: Set[str] = set()

    def _hash(self, key: str) -> int:
        if not isinstance(key, str):
            raise TypeError("Hash key must be a string.")
        # Using SHA-256 for a uniform distribution and collision resistance
        hasher = hashlib.sha256()
        hasher.update(key.encode('utf-8'))
        # Return a 64-bit integer from the first 8 bytes of the digest
        return int.from_bytes(hasher.digest()[:8], byteorder='big', signed=False)

    def add_node(self, node: str) -> None:
        if not node or not isinstance(node, str):
            raise ValueError("Node identifier must be a non-empty string.")
        if node in self.nodes:
            raise ValueError(f"Node '{node}' already exists in the ring.")

        self.nodes.add(node)
        for i in range(self.replicas):
            virtual_node_key = f"{node}#replica-{i}"
            hash_val = self._hash(virtual_node_key)

            # Handle extremely rare hash collisions gracefully
            while hash_val in self.ring_map:
                virtual_node_key += "#collision"
                hash_val = self._hash(virtual_node_key)

            idx = bisect.bisect_right(self.ring, hash_val)
            self.ring.insert(idx, hash_val)
            self.ring_map[hash_val] = node

    def remove_node(self, node: str) -> None:
        if not node or not isinstance(node, str):
            raise ValueError("Node identifier must be a non-empty string.")
        if node not in self.nodes:
            raise KeyError(f"Node '{node}' does not exist in the ring.")

        self.nodes.remove(node)
        hashes_to_remove = [h for h, n in self.ring_map.items() if n == node]

        for h in hashes_to_remove:
            idx = bisect.bisect_left(self.ring, h)
            if idx < len(self.ring) and self.ring[idx] == h:
                self.ring.pop(idx)
            del self.ring_map[h]

    def get_node(self, key: str) -> str:
        if not self.ring:
            raise RuntimeError("Cannot lookup key: The hash ring is empty.")
        if not key or not isinstance(key, str):
            raise ValueError("Lookup key must be a non-empty string.")

        hash_val = self._hash(key)
        idx = bisect.bisect_right(self.ring, hash_val)

        # Wrap around the ring if the hash is greater than all elements
        if idx == len(self.ring):
            idx = 0

        target_hash = self.ring[idx]
        return self.ring_map[target_hash]

    def get_nodes(self, key: str, count: int) -> List[str]:
        if not self.ring:
            raise RuntimeError("Cannot lookup keys: The hash ring is empty.")
        if count <= 0:
            raise ValueError("Count must be greater than zero.")
        if count > len(self.nodes):
            raise ValueError("Requested count exceeds total available physical nodes.")

        hash_val = self._hash(key)
        idx = bisect.bisect_right(self.ring, hash_val)
        if idx == len(self.ring):
            idx = 0

        selected_nodes: List[str] = []
        seen_nodes: Set[str] = set()
        start_idx = idx
        ring_len = len(self.ring)

        for i in range(ring_len):
            curr_idx = (start_idx + i) % ring_len
            node = self.ring_map[self.ring[curr_idx]]
            if node not in seen_nodes:
                seen_nodes.add(node)
                selected_nodes.append(node)
                if len(selected_nodes) == count:
                    break

        return selected_nodes
```

### Complexity Analysis

- **Time Complexity**:
  - **Initialization (`__init__`)**: $O(1)$.
  - **Add Node (`add_node`)**: $O(R \log (N \cdot R))$, where $R$ is the number of replicas per node and $N$ is the total number of physical nodes. This accounts for hashing and binary insertion into the sorted ring of size $N \cdot R$.
  - **Remove Node (`remove_node`)**: $O(N \cdot R + N \cdot R \log(N \cdot R))$ due to filtering matching virtual nodes and restructuring the ring list.
  - **Single Lookup (`get_node`)**: $O(\log(N \cdot R))$ via binary search (`bisect_right`) over the ring array.
  - **Multi-Node Lookup (`get_nodes`)**: $O(\log(N \cdot R) + C)$ where $C$ is the number of unique physical nodes fetched up to requirement count.

- **Space Complexity**:
  - $O(N \cdot R)$ space to store the physical-to-virtual mappings in `ring_map` and the sorted ring array of hash integers.

# Root Cause Analysis and Architectural Redesign: Deadlock Cycle Elimination in a Multi-Threaded Locking Engine

## 1. Executive Summary and Problem Statement
An enterprise distributed locking engine experienced intermittent, catastrophic deadlocks under peak transactional loads. Standard thread-dump analysis revealed threads blocked indefinitely inside resource acquisition corridors. This document provides a formal mathematical RCA of the deadlock cycles, proves the failure modes via resource allocation graph theory, and presents a comprehensive, thread-safe C++20 implementation using strict hierarchical lock ordering and non-blocking acquisition fallbacks.

## 2. Mathematical Formulation and Resource Allocation Graph Analysis

Let the concurrent system be modeled as a directed graph $G = (V, E)$, where $V = P \cup R$ represents the set of vertices partitioned into threads (Processes $P$) and shared Mutexes (Resources $R$). 

Edges in $E$ are classified into two disjoint sets:
1. **Assignment Edge**: $R_j \to P_i$, indicating resource $R_j$ is currently held by thread $P_i$.
2. **Request Edge**: $P_i \to R_j$, indicating thread $P_i$ is actively blocked waiting to acquire resource $R_j$.

### Coffman Conditions for Deadlock
A deadlock state occurs if and only if graph $G$ contains a directed cycle and all four Coffman conditions hold:
1. **Mutual Exclusion**: Resources can only be held by one thread at a time.
2. **Hold and Wait**: Thread $P_i$ holds resource $R_j$ while requesting resource $R_k$.
3. **No Preemption**: Resources cannot be forcibly expropriated from a thread.
4. **Circular Wait**: A closed chain of threads exists $\{P_1, P_2, \dots, P_n\}$ such that $P_1$ waits for $R_1$ held by $P_2$, $P_2$ waits for $R_2$ held by $P_3$, and $P_n$ waits for $R_n$ held by $P_1$.

### Proof of Deadlock Cycle
During peak load, threads executed dynamic locking across multiple independent shards without a global topological sorting order. Thread $T_1$ locked shard $S_A$ then requested $S_B$, while concurrently executing thread $T_2$ locked shard $S_B$ then requested $S_A$. 

Let $P = \{T_1, T_2\}$ and $R = \{S_A, S_B\}$.
- At time $t_1$: Edge set contains $S_A \to T_1$ and $S_B \to T_2$.
- At time $t_2$: $T_1$ requests $S_B$, adding request edge $T_1 \to S_B$.
- At time $t_3$: $T_2$ requests $S_A$, adding request edge $T_2 \to S_A$.

The resulting directed cycle $T_1 \to S_B \to T_2 \to S_A \to T_1$ satisfies the mathematical definition of a deadlock state, stalling execution indefinitely.

## 3. Production-Grade C++20 Implementation

To eradicate the circular wait condition, we enforce a strict global lock acquisition order using memory addresses as tie-breakers (resource valuation) combined with `std::scoped_lock` for deadlock avoidance via internal cycle-free lock algorithms.

```cpp
#include <iostream>
#include <vector>
#include <thread>
#include <mutex>
#include <shared_mutex>
#include <chrono>
#include <algorithm>
#include <exception>
#include <memory>

class ResourceShard {
private:
    mutable std::shared_mutex mtx_;
    uint64_t id_;
    uint64_t state_data_;

public:
    explicit ResourceShard(uint64_t id) : id_(id), state_data_(0) {}

    uint64_t get_id() const noexcept { return id_; }

    void modify_data(uint64_t val) {
        std::unique_lock<std::shared_mutex> lock(mtx_);
        state_data_ = val;
    }

    uint64_t read_data() const {
        std::shared_lock<std::shared_mutex> lock(mtx_);
        return state_data_;
    }

    // Expose raw mutex handle for lock algorithms while ensuring encapsulation
    std::shared_mutex& get_mutex() noexcept { return mtx_; }
};

class SafeLockManager {
public:
    // Transfers or processes state across multiple shards with guaranteed deadlock freedom
    template<typename Func>
    static void execute_atomic_operation(ResourceShard& shard_a,
                                         ResourceShard& shard_b,
                                         Func&& operation) {
        if (&shard_a == &shard_b) {
            std::unique_lock<std::shared_mutex> lock(shard_a.get_mutex());
            operation(shard_a, shard_b);
            return;
        }

        // Hierarchical lock ordering using pointer values to prevent circular wait
        std::unique_lock<std::shared_mutex> lock1;
        std::unique_lock<std::shared_mutex> lock2;

        if (&shard_a < &shard_b) {
            lock1 = std::unique_lock<std::shared_mutex>(shard_a.get_mutex());
            lock2 = std::unique_lock<std::shared_mutex>(shard_b.get_mutex());
        } else {
            lock1 = std::unique_lock<std::shared_mutex>(shard_b.get_mutex());
            lock2 = std::unique_lock<std::shared_mutex>(shard_a.get_mutex());
        }

        try {
            operation(shard_a, shard_b);
        } catch (const std::exception& e) {
            std::cerr << "Exception during atomic shard operation: " << e.what() << std::endl;
            throw;
        } catch (...) {
            std::cerr << "Unknown exception during atomic shard operation." << std::endl;
            throw;
        }
    }
};

int main() {
    try {
        auto shard1 = std::make_unique<ResourceShard>(1);
        auto shard2 = std::make_unique<ResourceShard>(2);

        std::thread t1([&]() {
            for (int i = 0; i < 100; ++i) {
                SafeLockManager::execute_atomic_operation(*shard1, *shard2, [](ResourceShard& a, ResourceShard& b) {
                    a.modify_data(a.read_data() + 1);
                    b.modify_data(b.read_data() + 1);
                });
            }
        });

        std::thread t2([&]() {
            for (int i = 0; i < 100; ++i) {
                // Pass in reverse order to test dynamic sorting resilience
                SafeLockManager::execute_atomic_operation(*shard2, *shard1, [](ResourceShard& a, ResourceShard& b) {
                    b.modify_data(b.read_data() + 1);
                    a.modify_data(a.read_data() + 1);
                });
            }
        });

        t1.join();
        t2.join();

        std::cout << "Execution completed successfully without deadlocks." << std::endl;
        std::cout << "Shard 1 value: " << shard1->read_data() << std::endl;
        std::cout << "Shard 2 value: " << shard2->read_data() << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Fatal Error: " << e.what() << std::endl;
        return 1;
    }
    return 0;
}
```

## 4. Complexity Analysis

### Time Complexity
- **Lock Acquisition Phase**: Sorting and acquiring $K$ unique mutexes takes $\mathcal{O}(K \log K)$ due to pointer comparison sorting, where $K$ is the number of target resources. For $K=2$, this reduces to $\mathcal{O}(1)$ direct branch evaluation.
- **Critical Section Execution**: Bounded by the user-supplied lambda execution time $\mathcal{O}(F)$.
- **Overall Time Complexity**: $\mathcal{O}(K \log K + F)$ per atomic transaction.

### Space Complexity
- **Auxiliary Space**: $\mathcal{O}(K)$ space overhead to store references or unique lock handles in arrays/tuples during multi-lock acquisition.
- **Overall Space Complexity**: $\mathcal{O}(K)$ where $K$ represents the concurrent depth of acquired mutexes.

## 5. Edge Cases, Failure Modes, and Trade-Offs

1. **Aliasing and Self-Deadlock**: 
   - *Edge Case*: Passing the exact same resource reference twice (`shard_a` and `shard_b` point to the same object). 
   - *Mitigation*: Explicitly checked via `&shard_a == &shard_b` to bypass double-locking attempts on non-reentrant mutexes (`std::shared_mutex`), preventing immediate self-deadlocks.

2. **Priority Inversion**: 
   - *Trade-Off*: Hierarchical locking establishes deterministic order but does not inherently solve priority inversion if a low-priority thread holds a globally low-address mutex. 
   - *Mitigation*: Real-time operating systems must utilize priority inheritance protocols at the OS scheduler level.

3. **Starvation Under High Contention**: 
   - *Failure Mode*: Writers can experience starvation if readers continuously hold shared locks.
   - *Mitigation*: `std::shared_mutex` implementations in modern standard libraries favor writers or implement fair queueing policies depending on the underlying OS primitives.

Here is the production-grade implementation of a high-performance SPSC lock-free ring buffer in C++20.

### C++20 SPSC Ring Buffer Implementation

```cpp
#include <atomic>
#include <new>
#include <iostream>
#include <thread>
#include <vector>
#include <cassert>

// Define cache line size to prevent false sharing
#ifdef __cpp_lib_hardware_interference_size
using std::hardware_destructive_interference_size;
#else
constexpr size_t hardware_destructive_interference_size = 64;
#endif

template <typename T, size_t Capacity>
class SPSCRingBuffer {
    static_assert((Capacity & (Capacity - 1)) == 0, "Capacity must be a power of two.");

public:
    SPSCRingBuffer() : head_(0), tail_(0) {}

    ~SPSCRingBuffer() = default;

    SPSCRingBuffer(const SPSCRingBuffer&) = delete;
    SPSCRingBuffer& operator=(const SPSCRingBuffer&) = delete;
    SPSCRingBuffer(SPSCRingBuffer&&) = delete;
    SPSCRingBuffer& operator=(SPSCRingBuffer&&) = delete;

    template <typename... Args>
    bool emplace(Args&&... args) {
        const size_t current_tail = tail_.load(std::memory_order_relaxed);
        const size_t current_head = head_.load(std::memory_order_acquire);

        if ((current_tail - current_head) >= Capacity) {
            return false; // Full
        }

        // Construct directly into the underlying storage
        new (&buffer_[current_tail & kMask]) T(std::forward<Args>(args)...);

        // Publish the write
        tail_.store(current_tail + 1, std::memory_order_release);
        return true;
    }

    bool push(const T& item) {
        return emplace(item);
    }

    bool push(T&& item) {
        return emplace(std::move(item));
    }

    bool pop(T& item) {
        const size_t current_head = head_.load(std::memory_order_relaxed);
        const size_t current_tail = tail_.load(std::memory_order_acquire);

        if (current_head == current_tail) {
            return false; // Empty
        }

        T* ptr = reinterpret_cast<T*>(&buffer_[current_head & kMask]);
        item = std::move(*ptr);
        ptr->~T();

        // Publish the read
        head_.store(current_head + 1, std::memory_order_release);
        return true;
    }

    [[nodiscard]] bool empty() const noexcept {
        return head_.load(std::memory_order_acquire) == tail_.load(std::memory_order_acquire);
    }

    [[nodiscard]] size_t size() const noexcept {
        size_t current_head = head_.load(std::memory_order_acquire);
        size_t current_tail = tail_.load(std::memory_order_acquire);
        return (current_tail >= current_head) ? (current_tail - current_head) : 0;
    }

private:
    static constexpr size_t kMask = Capacity - 1;

    // Storage aligned to prevent false sharing
    struct Node {
        alignas(T) char storage[sizeof(T)];
    };

    alignas(hardware_destructive_interference_size) std::atomic<size_t> head_;
    alignas(hardware_destructive_interference_size) std::atomic<size_t> tail_;
    alignas(hardware_destructive_interference_size) Node buffer_[Capacity];
};

int main() {
    constexpr size_t kCapacity = 8;
    SPSCRingBuffer<int, kCapacity> ring_buffer;

    std::thread producer([&]() {
        for (int i = 0; i < 100; ++i) {
            while (!ring_buffer.push(i)) {
                std::this_thread::yield();
            }
        }
    });

    std::thread consumer([&]() {
        int val = 0;
        int consumed = 0;
        while (consumed < 100) {
            if (ring_buffer.pop(val)) {
                assert(val == consumed);
                consumed++;
            } else {
                std::this_thread::yield();
            }
        }
        std::cout << "Successfully consumed " << consumed << " elements sequentially.\n";
    });

    producer.join();
    consumer.join();
    return 0;
}
```

### Complexity Analysis

- **Time Complexity:**
  - `push()` / `pop()`: $\mathcal{O}(1)$ constant time operations since index masking avoids expensive modulo computations and operations bypass locks.
  - `size()` / `empty()`: $\mathcal{O}(1)$ constant time atomic reads.

- **Space Complexity:**
  - $\mathcal{O}(C)$ where $C$ is the `Capacity` template parameter, storing an array of uninitialized storage blocks plus metadata variables padded to hardware cache line boundaries to completely prevent false sharing.

Here is the production-grade implementation of a Cache-Aligned Memory Arena Pool allocator in C++17. It manages memory in large underlying chunks, satisfies arbitrary alignment requirements without internal fragmentation per allocation, and enables O(1) bulk resets.

```cpp
#include <iostream>
#include <vector>
#include <cstdint>
#include <cstddef>
#include <new>
#include <utility>
#include <cassert>

class MemoryArena {
private:
    struct Chunk {
        std::byte* data;
        size_t capacity;
        size_t used;
        Chunk* next;

        Chunk(size_t cap, Chunk* nxt)
            : capacity(cap), used(0), next(nxt) {
            // Allocate with explicit 64-byte cache-line alignment
            #if defined(_MSC_VER)
            data = static_cast<std::byte*>(_aligned_malloc(capacity, 64));
            #else
            if (posix_memalign(reinterpret_cast<void**>(&data), 64, capacity) != 0) {
                data = nullptr;
            }
            #endif
            if (!data) {
                throw std::bad_alloc();
            }
        }

        ~Chunk() {
            #if defined(_MSC_VER)
            _aligned_free(data);
            #else
            free(data);
            #endif
        }

        // Non-copyable, non-movable for safety
        Chunk(const Chunk&) = delete;
        Chunk& operator=(const Chunk&) = delete;
    };

    size_t chunk_size_;
    Chunk* current_chunk_;
    size_t total_allocated_memory_;

    void allocate_new_chunk(size_t min_capacity) {
        size_t actual_capacity = std::max(chunk_size_, min_capacity);
        // Pad to ensure cache-line multiples
        size_t remainder = actual_capacity % 64;
        if (remainder != 0) {
            actual_capacity += (64 - remainder);
        }
        current_chunk_ = new Chunk(actual_capacity, current_chunk_);
        total_allocated_memory_ += actual_capacity;
    }

public:
    explicit MemoryArena(size_t default_chunk_size = 4096) 
        : chunk_size_(default_chunk_size), current_chunk_(nullptr), total_allocated_memory_(0) {
        if (chunk_size_ < 64) {
            chunk_size_ = 64;
        }
        allocate_new_chunk(chunk_size_);
    }

    ~MemoryArena() {
        reset();
    }

    // Non-copyable
    MemoryArena(const MemoryArena&) = delete;
    MemoryArena& operator=(const MemoryArena&) = delete;

    // Movable
    MemoryArena(MemoryArena&& other) noexcept 
        : chunk_size_(other.chunk_size_), 
          current_chunk_(other.current_chunk_), 
          total_allocated_memory_(other.total_allocated_memory_) {
        other.chunk_size_ = 4096;
        other.current_chunk_ = nullptr;
        other.total_allocated_memory_ = 0;
    }

    MemoryArena& operator=(MemoryArena&& other) noexcept {
        if (this != &other) {
            reset();
            chunk_size_ = other.chunk_size_;
            current_chunk_ = other.current_chunk_;
            total_allocated_memory_ = other.total_allocated_memory_;
            other.chunk_size_ = 4096;
            other.current_chunk_ = nullptr;
            other.total_allocated_memory_ = 0;
        }
        return *this;
    }

    void* allocate(size_t size, size_t alignment = alignof(std::max_align_t)) {
        assert(size > 0 && "Allocation size must be greater than zero.");

        if (alignment < 64) {
            alignment = 64; // Force strict cache-line alignment minimum for performance
        }

        uintptr_t current_address = reinterpret_cast<uintptr_t>(current_chunk_->data + current_chunk_->used);
        size_t padding = (alignment - (current_address % alignment)) % alignment;
        size_t total_needed = size + padding;

        if (current_chunk_->used + total_needed > current_chunk_->capacity) {
            // Allocate a new chunk if current does not have space
            size_t required_cap = std::max(chunk_size_, total_needed + 64);
            allocate_new_chunk(required_cap);

            current_address = reinterpret_cast<uintptr_t>(current_chunk_->data + current_chunk_->used);
            padding = (alignment - (current_address % alignment)) % alignment;
            total_needed = size + padding;
        }

        std::byte* aligned_ptr = current_chunk_->data + current_chunk_->used + padding;
        current_chunk_->used += total_needed;

        return static_cast<void*>(aligned_ptr);
    }

    template <typename T, typename... Args>
    T* create(Args&&... args) {
        void* mem = allocate(sizeof(T), alignof(T));
        return ::new (mem) T(std::forward<Args>(args)...);
    }

    void reset() noexcept {
        Chunk* current = current_chunk_;
        while (current != nullptr) {
            Chunk* next_chunk = current->next;
            delete current;
            current = next_chunk;
        }
        current_chunk_ = nullptr;
        total_allocated_memory_ = 0;
        allocate_new_chunk(chunk_size_);
    }

    size_t get_total_allocated_memory() const noexcept {
        return total_allocated_memory_;
    }
};

struct Node {
    int id;
    double value;
    Node(int i, double v) : id(i), value(v) {}
};

int main() {
    try {
        MemoryArena arena(1024);

        // Allocate fundamental types
        int* numbers = static_cast<int*>(arena.allocate(10 * sizeof(int), alignof(int)));
        for (int i = 0; i < 10; ++i) {
            numbers[i] = i * 10;
        }

        // Construct complex objects using placement new helper
        Node* node1 = arena.create<Node>(1, 3.14159);
        Node* node2 = arena.create<Node>(2, 2.71828);

        std::cout << "Node 1 ID: " << node1->id << ", Value: " << node1->value << std::endl;
        std::cout << "Node 2 ID: " << node2->id << ", Value: " << node2->value << std::endl;
        std::cout << "Total Arena Memory Allocated: " << arena.get_total_allocated_memory() << " bytes" << std::endl;

        // Bulk reset clears everything instantaneously
        arena.reset();
        std::cout << "Arena reset successfully. Memory reclaimed." << std::endl;

    } catch (const std::exception& e) {
        std::cerr << "Exception caught: " << e.what() << std::endl;
        return 1;
    }

    return 0;
}
```

### Complexity Analysis
- **Time Complexity**:
  - **Allocation (`allocate`)**: $\mathcal{O}(1)$ amortized. In the common case, it performs simple pointer arithmetic and offset tracking. If a chunk overflows, allocating a new backing chunk requires $\mathcal{O}(1)$ system calls (e.g., `posix_memalign`).
  - **Object Construction (`create`)**: $\mathcal{O}(1)$ plus the construction time complexity of type `T`.
  - **Reset (`reset`)**: $\mathcal{O}(N)$ where $N$ is the number of underlying chunks allocated. Since $N$ is typically very small due to large chunk sizing, this executes in near-instantaneous time.

- **Space Complexity**:
  - **Auxiliary Space**: $\mathcal{O}(C)$ where $C$ is the total metadata overhead per chunk (pointers and size tracking values, totaling negligible fixed bytes per chunk).
  - **Fragmentation Overhead**: $\mathcal{O}(1)$ internal fragmentation limited strictly to alignment padding per request and unused trailing space in the active chunk upon chunk transitions.

