    shared: Arc<Mutex<Shared<T>>>,
    not_full: Arc<Condvar>,
    not_empty: Arc<Condvar>,
    dropped: AtomicBool,
}

pub struct Receiver<T> {
    shared: Arc<Mutex<Shared<T>>>,
    not_full: Arc<Condvar>,
    not_empty: Arc<Condvar>,
    dropped: AtomicBool,
}

pub fn channel<T>(capacity: usize) -> (Sender<T>, Receiver<T>) {
    assert!(capacity > 0, "Channel capacity must be greater than zero");
    let shared = Arc::new(Mutex::new(Shared {
        buffer: (0..capacity).map(|_| None).collect(),
        head: 0,
        tail: 0,
        len: 0,
        capacity,
        senders_count: 1,
        receivers_count: 1,
        is_shutdown: false,
    }));

    let not_full = Arc::new(Condvar::new());
    let not_empty = Arc::new(Condvar::new());

    let sender = Sender {
        shared: Arc::clone(&shared),
        not_full: Arc::clone(&not_full),
        not_empty: Arc::clone(&not_empty),
        dropped: AtomicBool::new(false),
    };

    let receiver = Receiver {
        shared,
        not_full,
        not_empty,
        dropped: AtomicBool::new(false),
    };

    (sender, receiver)
}

impl<T> Sender<T> {
    pub fn send(&self, mut value: T) -> Result<(), ChannelError<T>> {
        let mut shared = self.shared.lock().unwrap();

        while shared.len == shared.capacity && !shared.is_shutdown {
            shared = self.not_full.wait(shared).unwrap();
        }

        if shared.is_shutdown {
            return Err(ChannelError::Shutdown);
        }

        if shared.senders_count == 0 {
            return Err(ChannelError::Disconnected(value));
        }

        let tail = shared.tail;
        shared.buffer[tail] = Some(value);
        shared.tail = (tail + 1) % shared.capacity;
        shared.len += 1;

        self.not_empty.notify_one();
        Ok(())
    }
}

impl<T> Clone for Sender<T> {
    fn clone(&self) -> Self {
        let mut shared = self.shared.lock().unwrap();
        shared.senders_count += 1;
        Sender {
            shared: Arc::clone(&self.shared),
            not_full: Arc::clone(&self.not_full),
            not_empty: Arc::clone(&self.not_empty),
            dropped: AtomicBool::new(false),
        }
    }
}

impl<T> Drop for Sender<T> {
    fn drop(&mut self) {
        if self.dropped.swap(true, Ordering::AcqRel) {
            return;
        }
        let mut shared = self.shared.lock().unwrap();
        shared.senders_count -= 1;
        if shared.senders_count == 0 {
            shared.is_shutdown = true;
            self.not_empty.notify_all();
            self.not_full.notify_all();
        }
    }
}

impl<T> Receiver<T> {
    pub fn recv(&self) -> Result<T, ChannelError<()>> {
        let mut shared = self.shared.lock().unwrap();

        while shared.len == 0 && !shared.is_shutdown {
            if shared.senders_count == 0 {
                return Err(ChannelError::Disconnected(()));
            }
            shared = self.not_empty.wait(shared).unwrap();
        }

        if shared.len == 0 && shared.is_shutdown {
            return Err(ChannelError::Shutdown);
        }

        let head = shared.head;
        let value = shared.buffer[head].take().unwrap();
        shared.head = (head + 1) % shared.capacity;
        shared.len -= 1;

        self.not_full.notify_one();
        Ok(())
    }
}

impl<T> Clone for Receiver<T> {
    fn clone(&self) -> Self {
        let mut shared = self.shared.lock().unwrap();
        shared.receivers_count += 1;
        Receiver {
            shared: Arc::clone(&self.shared),
            not_full: Arc::clone(&self.not_full),
            not_empty: Arc::clone(&self.not_empty),
            dropped: AtomicBool::new(false),
        }
    }
}

impl<T> Drop for Receiver<T> {
    fn drop(&mut self) {
        if self.dropped.swap(true, Ordering::AcqRel) {
            return;
        }
        let mut shared = self.shared.lock().unwrap();
        shared.receivers_count -= 1;
        if shared.receivers_count == 0 {
            shared.is_shutdown = true;
            self.not_empty.notify_all();
            self.not_full.notify_all();
        }
    }
}

fn main() {
    let (tx, rx) = channel(4);
    let mut handles = vec![];

    for i in 03 {
        let tx_clone = tx.clone();
        handles.push(thread::spawn(move || {
            for j in 03 {
                let val = i * 10 + j;
                tx_clone.send(val).unwrap();
                println!("Produced: {}", val);
            }
        }));
    }
    drop(tx);

    for _ in 02 {
        let rx_clone = rx.clone();
        handles.push(thread::spawn(move || {
            while let Ok(val) = rx_clone.recv() {
                println!("Consumed: {}", val);
                thread::sleep(Duration::from_millis(10));
            }
        }));
    }
    drop(rx);

    for handle in handles {
        handle.join().unwrap();
    }
    println!("Channel execution completed successfully.");
}
